    ArgDef { id: "until_success", short: Some('s'), long: "until-success", value_name: None, default: None, validator: Validator::None },
    ArgDef { id: "version", short: Some('V'), long: "version", value_name: None, default: None, validator: Validator::None },
    ArgDef { id: "count_by", short: Some('b'), long: "count-by", value_name: Some("count_by"), default: Some("1"), validator: Validator::Float },
    ArgDef { id: "every", short: Some('e'), long: "every", value_name: Some("every"), default: Some("1us"), validator: Validator::Duration },
    ArgDef { id: "ffor", short: None, long: "for", value_name: Some("ffor"), default: None, validator: Validator::None },
    ArgDef { id: "for_duration", short: Some('d'), long: "for-duration", value_name: Some("for_duration"), default: None, validator: Validator::Duration },
    ArgDef { id: "num", short: Some('n'), long: "num", value_name: Some("num"), default: None, validator: Validator::Float },
    ArgDef { id: "offset", short: Some('o'), long: "offset", value_name: Some("offset"), default: Some("0"), validator: Validator::Float },
    ArgDef { id: "until_contains", short: Some('c'), long: "until-contains", value_name: Some("until_contains"), default: None, validator: Validator::None },
    ArgDef { id: "until_error", short: Some('r'), long: "until-error", value_name: Some("until_error"), default: None, validator: Validator::None },
    ArgDef { id: "until_match", short: Some('m'), long: "until-match", value_name: Some("until_match"), default: None, validator: Validator::Regex },
    ArgDef { id: "until_time", short: Some('t'), long: "until-time", value_name: Some("until_time"), default: None, validator: Validator::Timestamp },
];

fn def_by_id(id: &str) -> &'static ArgDef {
    DEFS.iter().find(|d| d.id == id).unwrap()
}
fn find_long(long: &str) -> Option<&'static ArgDef> {
    DEFS.iter().find(|d| d.long == long)
}
fn find_short(short: char) -> Option<&'static ArgDef> {
    DEFS.iter().find(|d| d.short == Some(short))
}

struct Token {
    text: String,
    raw: Vec<u8>,
    invalid_utf8: bool,
}
impl Token {
    fn from_os(s: OsString) -> Self {
        let raw = s.as_bytes().to_vec();
        let invalid_utf8 = s.to_str().is_none();
        Token { text: s.to_string_lossy().into_owned(), raw, invalid_utf8 }
    }
}

struct Parsed {
    bin_name: String,
    app_name: String,
    occurrences: HashMap<&'static str, usize>,
    occurrence_order: Vec<&'static str>,
    values: HashMap<&'static str, Vec<String>>,
    invalid_value_ids: HashSet<&'static str>,
    input: Vec<String>,
    input_invalid_utf8: bool,
}
impl Parsed {
    fn new(bin_name: String, app_name: String) -> Self {
        Parsed {
            bin_name,
            app_name,
            occurrences: HashMap::new(),
            occurrence_order: Vec::new(),
            values: HashMap::new(),
            invalid_value_ids: HashSet::new(),
            input: Vec::new(),
            input_invalid_utf8: false,
        }
    }
    fn record(&mut self, def: &'static ArgDef) {
        let e = self.occurrences.entry(def.id).or_insert(0);
        if *e == 0 {
            self.occurrence_order.push(def.id);
        }
        *e += 1;
    }
    fn add_value(&mut self, def: &'static ArgDef, value: String, invalid: bool) {
        self.values.entry(def.id).or_default().push(value);
        if invalid {
            self.invalid_value_ids.insert(def.id);
        }
    }
    fn is_present(&self, id: &str) -> bool {
        self.occurrences.get(id).copied().unwrap_or(0) > 0
    }
    fn explicit_value(&self, id: &str) -> Option<&str> {
        self.values.get(id).and_then(|v| v.first()).map(|s| s.as_str())
    }
    fn effective_value(&self, id: &str) -> Option<&str> {
        if let Some(v) = self.explicit_value(id) {
            return Some(v);
        }
        def_by_id(id).default
    }
    fn used_ids(&self) -> HashSet<&'static str> {
        self.occurrence_order.iter().copied().collect()
    }
}

fn stderr_color() -> bool {
    io::stderr().is_terminal()
}

fn usage_line(bin_name: &str, used: &HashSet<&'static str>, include_defaults: bool) -> String {
    let mut set: HashSet<&'static str> = used.clone();
    if include_defaults {
        for d in DEFS {
            if d.default.is_some() {
                set.insert(d.id);
            }
        }
    }
    if set.is_empty() {
        return format!("{} [FLAGS] [OPTIONS] [input]...", bin_name);
    }
    let mut defs: Vec<&ArgDef> = DEFS.iter().filter(|d| set.contains(d.id)).collect();
    defs.sort_by(|a, b| a.long.cmp(b.long));
    let parts: Vec<String> = defs.iter().map(|d| d.display()).collect();
    format!("{} {}", bin_name, parts.join(" "))
}

fn error_prefix(color: bool) -> &'static str {
    if color { "\x1b[1;31merror:\x1b[0m" } else { "error:" }
}
fn color_arg(text: &str, color: bool) -> String {
    if color { format!("\x1b[33m{}\x1b[0m", text) } else { text.to_string() }
}
fn usage_footer(color: bool) -> &'static str {
    if color {
        "For more information try \x1b[32m--help\x1b[0m\n"
    } else {
        "For more information try --help\n"
    }
}

fn fail_unknown(bin_name: &str, arg_display: &str, suggestion: Option<&'static ArgDef>, used: HashSet<&'static str>) -> ! {
    let color = stderr_color();
    let mut used = used;
    if let Some(d) = suggestion {
        used.insert(d.id);
    }
    let mut out = String::new();
    out.push_str(&format!(
        "{} Found argument '{}' which wasn't expected, or isn't valid in this context\n",
        error_prefix(color),
        color_arg(arg_display, color)
    ));
    if let Some(d) = suggestion {
        out.push_str(&format!(
            "\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?\n",
            d.long
        ));
    }
    out.push_str(&format!(
        "\nUSAGE:\n    {}\n\n{}",
        usage_line(bin_name, &used, false),
        usage_footer(color)
    ));
    eprint!("{}", out);
    process::exit(1);
}

fn fail_missing(bin_name: &str, def: &ArgDef, used: HashSet<&'static str>) -> ! {
    let color = stderr_color();
    eprint!(
        "{} The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\n{}",
        error_prefix(color),
        color_arg(&def.display(), color),
        usage_line(bin_name, &used, true),
        usage_footer(color)
    );
    process::exit(1);
}
fn fail_duplicate(bin_name: &str, def: &ArgDef, used: HashSet<&'static str>) -> ! {
    let color = stderr_color();
    eprint!(
        "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}\n\n{}",
        error_prefix(color),
        color_arg(&def.display(), color),
        usage_line(bin_name, &used, true),
        usage_footer(color)
    );
    process::exit(1);
}
fn fail_invalid(def: &ArgDef, msg: &str) -> ! {
    let color = stderr_color();
    eprint!(
        "{} Invalid value for '{}': {}\n",
        error_prefix(color),
        color_arg(&def.display(), color),
        msg
    );
    process::exit(1);
}

fn help_text(bin_name: &str, app_name: &str) -> String {
    format!(
        "{app} {version}\n\
