fn fake_panic(location: &str, msg: &str) -> ! {
    let pid = process::id();
    let backtrace = env::var_os("RUST_BACKTRACE")
        .map(|v| v.to_string_lossy().into_owned())
        .unwrap_or_default();
    if !backtrace.is_empty() && backtrace != "0" {
        eprint!(
            "\nthread 'main' ({}) panicked at {}:\n{}\nstack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n",
