                );
            }
            let trimmed = token.text.trim_start_matches('-');
            let (name, inline_value): (&str, Option<String>) = match trimmed.find('=') {
                Some(p) => (
                    &trimmed[..p],
                    Some(trimmed[p + 1..].trim_start_matches('=').to_string()),
                ),
                None => (trimmed, None),
            };
            match find_long(name) {
                Some(def) => {
                    parsed.record(def);
                    if def.id == "help" {
                        print_help_and_exit(&parsed.bin_name, &parsed.app_name);
                    }
                    if def.id == "version" {
                        print_version_and_exit(&parsed.app_name);
                    }
                    if def.is_option() {
                        if let Some(v) = inline_value {
                            parsed.add_value(def, v, token.invalid_utf8);
                        } else {
                            pending = Some(def);
                        }
                    }
                    // Long flags silently ignore an inline =value in clap 2.
                }
                None => {
                    let suggestion = did_you_mean(name);
                    fail_unknown(
                        &parsed.bin_name.clone(),
                        &format!("--{}", name),
                        suggestion,
                        parsed.used_ids(),
                    );
                }
            }
            continue;
        }

        if token.text.starts_with('-') && token.text != "-" {
            let cluster = &token.text[1..];
            let mut chars = cluster.char_indices();
            while let Some((idx, ch)) = chars.next() {
                match find_short(ch) {
                    Some(def) => {
                        parsed.record(def);
                        if def.id == "help" {
                            print_help_and_exit(&parsed.bin_name, &parsed.app_name);
                        }
                        if def.id == "version" {
                            print_version_and_exit(&parsed.app_name);
                        }
                        if def.is_option() {
                            let rest = &cluster[idx + ch.len_utf8()..];
                            if !rest.is_empty() {
                                let v = rest.trim_start_matches('=').to_string();
                                parsed.add_value(def, v, token.invalid_utf8);
                            } else {
                                pending = Some(def);
                            }
                            break;
                        }
                    }
                    None => {
                        fail_unknown(
                            &parsed.bin_name.clone(),
                            &format!("-{}", ch),
                            None,
                            parsed.used_ids(),
                        );
                    }
                }
            }
            continue;
        }

        parsed.input.push(token.text.clone());
        parsed.input_invalid_utf8 |= token.invalid_utf8;
    }

    validate(&parsed);
    parsed
}

fn validate(parsed: &Parsed) {
    for &id in &parsed.occurrence_order {
        let def = def_by_id(id);
        let occ = parsed.occurrences.get(id).copied().unwrap_or(0);
        if !def.is_option() {
            if occ > 1 {
                fail_duplicate(&parsed.bin_name, def, parsed.used_ids());
            }
            continue;
        }
        let vals: &[String] = parsed.values.get(id).map(|v| &v[..]).unwrap_or(&[]);
        for v in vals {
            if let Err(msg) = run_validator(def, v) {
                fail_invalid(def, &msg);
            }
        }
        if vals.is_empty() {
            if def.default.is_none() {
                fail_missing(&parsed.bin_name, def, parsed.used_ids());
            } else if occ > 1 {
                fail_duplicate(&parsed.bin_name, def, parsed.used_ids());
            }
        } else if occ > 1 {
            fail_duplicate(&parsed.bin_name, def, parsed.used_ids());
        }
    }
}

fn run_validator(def: &ArgDef, value: &str) -> Result<(), String> {
    match def.validator {
        Validator::None => Ok(()),
        Validator::Float => value.parse::<f64>().map(|_| ()).map_err(|e| e.to_string()),
        Validator::Duration => parse_duration(value).map(|_| ()),
        Validator::Timestamp => parse_timestamp(value).map(|_| ()).map_err(|e| e.to_string()),
        Validator::Regex => validate_regex(value),
    }
}

fn validate_regex(value: &str) -> Result<(), String> {
    // The original uses an older regex version. Preserve two conspicuous
    // old-version behaviours before falling back to the regex crate.
    if let Some(err) = check_old_named_and_flag_syntax(value) {
        return Err(err);
    }
    match Regex::new(value) {
        Ok(_) => {
            if regex_has_empty_alternation(value) {
                Err("alternations cannot currently contain empty sub-expressions".to_string())
            } else {
                Ok(())
            }
        }
        Err(e) => Err(e.to_string()),
    }
}

fn char_at(chars: &[(usize, char)], idx: usize) -> Option<char> {
    chars.get(idx).map(|x| x.1)
}

// Detect (?<name>...) and the unsupported R flag in the style used by the
// older regex parser. Escapes and character classes are ignored.
fn check_old_named_and_flag_syntax(value: &str) -> Option<String> {
    let chars: Vec<(usize, char)> = value.char_indices().collect();
    let mut i = 0usize;
    let mut in_class = false;
    while i < chars.len() {
        let c = chars[i].1;
        if c == '\\' {
            i += 2;
            continue;
        }
        if in_class {
            if c == ']' {
                in_class = false;
            }
            i += 1;
            continue;
        }
        if c == '[' {
            in_class = true;
            i += 1;
            continue;
        }
        if c == '(' && char_at(&chars, i + 1) == Some('?') {
            // (?<name>) was read as (? followed by flag '<'.
            if char_at(&chars, i + 2) == Some('<')
                && char_at(&chars, i + 3) != Some('=')
                && char_at(&chars, i + 3) != Some('!')
            {
                let at = chars[i + 2].0;
                return Some(format(
                    "regex parse error:\n    {}\n    {}^\nerror: unrecognized flag",
                    value,
                    " ".repeat(at)
                ));
            }
            if char_at(&chars, i + 2) == Some('P') && char_at(&chars, i + 3) == Some('<') {
                // Let the modern parser handle named captures.
                i += 2;
                continue;
            }
            // Scan a flag group (?flags) or (?flags:...), where R was
            // not a recognised flag in the older version.
            let mut j = i + 2;
            let mut neg = false;
            while let Some(fc) = char_at(&chars, j) {
                if fc == ')' || fc == ':' {
                    break;
                }
                if fc == '-' {
                    neg = true;
                    j += 1;
                    continue;
                }
                if fc == 'R' {
                    let at = chars[j].0;
                    return Some(format(
                        "regex parse error:\n    {}\n    {}^\nerror: unrecognized flag",
                        value,
                        " ".repeat(at)
                    ));
                }
                if !"imsxuU".contains(fc) {
                    break;
                }
                let _ = neg;
                j += 1;
            }
        }
        i += 1;
    }
    None
}

// A reasonably complete syntactic test for an alternation branch that is
// empty, made only of an empty group, or made only of a flag directive.
fn regex_has_empty_alternation(value: &str) -> bool {
    // Split each parenthesis level into branches, tracking whether the
    // branch contains anything other than empty groups/flag directives.
    // Character classes count as content; escaped characters count.
    #[derive(Default)]
    struct Level {
        has_content: bool,
        has_alternation: bool,
    }
    let chars: Vec<char> = value.chars().collect();
    let mut stack: Vec<Level> = vec![Level::default()];
    let mut i = 0usize;
    while i < chars.len() {
        let c = chars[i];
        if c == '\\' {
            if let Some(l) = stack.last_mut() { l.has_content = true; }
            i += 2;
            continue;
        }
        if c == '[' {
            if let Some(l) = stack.last_mut() { l.has_content = true; }
            i += 1;
            // Skip class; an initial ] is a literal in regex syntax.
            if i < chars.len() && chars[i] == '^' { i += 1; }
            if i < chars.len() && chars[i] == ']' { i += 1; }
            while i < chars.len() {
                if chars[i] == '\\' { i += 2; continue; }
                if chars[i] == ']' { break; }
                i += 1;
            }
            i += 1;
            continue;
        }
        if c == '(' {
            // A flag directive (?flags) (not (?flags:...)) does not add
            // expression content in the old compiler's eyes.
            if i + 1 < chars.len() && chars[i + 1] == '?' {
                let mut j = i + 2;
                let mut directive = false;
                let mut group = false;
                while j < chars.len() {
                    if chars[j] == ')' { directive = true; break; }
                    if chars[j] == ':' { group = true; break; }
                    if chars[j] == '<' || chars[j] == 'P' { group = true; break; }
                    if !"imsxuU-R".contains(chars[j]) { break; }
                    j += 1;
                }
                if directive {
                    i = j + 1;
                    continue;
                }
                let _ = group;
            }
            stack.push(Level::default());
            i += 1;
            continue;
        }
        if c == ')' {
            if stack.len() <= 1 {
                return false;
            }
            let done = stack.pop().unwrap();
            if done.has_alternation && !done.has_content {
                return true;
            }
            // An empty group used as a whole branch is still empty; a
            // non-empty group is content for its parent.
            if done.has_content {
                if let Some(l) = stack.last_mut() { l.has_content = true; }
            }
            i += 1;
            continue;
        }
        if c == '|' {
            if let Some(l) = stack.last_mut() {
                if !l.has_content {
                    return true;
                }
                l.has_content = false;
                l.has_alternation = true;
            }
            i += 1;
            continue;
        }
        if let Some(l) = stack.last_mut() { l.has_content = true; }
        i += 1;
    }
    if let Some(top) = stack.last() {
        if top.has_alternation && !top.has_content {
            return true;
        }
    }
    false
}

fn jaro(a: &[char], b: &[char]) -> f64 {
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    if a == b {
        return 1.0;
    }
    let search_range = (a.len().max(b.len()) / 2).saturating_sub(1);
    let mut a_match = vec![false; a.len()];
    let mut b_match = vec![false; b.len()];
    let mut matches = 0usize;
    for i in 0..a.len() {
        let lo = i.saturating_sub(search_range);
        let hi = (i + search_range + 1).min(b.len());
        for j in lo..hi {
            if !b_match[j] && a[i] == b[j] {
                a_match[i] = true;
                b_match[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..a.len() {
        if a_match[i] {
            while !b_match[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (t / 2) as f64) / m) / 3.0
}

fn jaro_winkler(a_str: &str, b_str: &str) -> f64 {
    let a: Vec<char> = a_str.chars().collect();
    let b: Vec<char> = b_str.chars().collect();
    let sim = jaro(&a, &b);
    if sim > 0.7 {
        let mut prefix = 0usize;
        for i in 0..a.len().min(b.len()) {
            if a[i] == b[i] && prefix < 4 {
                prefix += 1;
            } else {
                break;
            }
        }
        sim + (0.1 * prefix as f64 * (1.0 - sim))
    } else {
        sim
    }
}

fn did_you_mean(value: &str) -> Option<&'static ArgDef> {
    // Candidate order only matters for exact-confidence ties. The order is
    // chosen so that the common "--until" tie yields --until-same, as the
    // observed program does.
    const CANDIDATE_ORDER: &[&str] = &[
        "help", "version", "error-duration", "only-last", "stdin", "summary",
        "until-changes", "until-same", "until-fail", "until-success",
        "count-by", "every", "for", "for-duration", "num", "offset",
        "until-contains", "until-error", "until-match", "until-time",
    ];
    let mut best: Option<(f64, &'static ArgDef)> = None;
    for long in CANDIDATE_ORDER {
        let def = find_long(long).unwrap();
        let conf = jaro_winkler(value, long);
        if conf > 0.8 {
            match best {
                Some((best_conf, _)) if conf <= best_conf => {}
                _ => best = Some((conf, def)),
            }
        }
    }
    best.map(|(_, d)| d)
}

// ----- humantime-like duration parsing -----

#[derive(Debug)]
enum DurationError {
    Empty,
    ExpectedNumber(usize),
    InvalidCharacter(usize),
    UnknownUnit(usize, usize),
    NumberTooLarge,
}
impl std::fmt::Display for DurationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DurationError::Empty => write!(f, "value was empty"),
            DurationError::ExpectedNumber(n) => write!(f, "expected number at {}", n),
            DurationError::InvalidCharacter(n) => write!(f, "invalid character at {}", n),
            DurationError::UnknownUnit(a, b) => write!(f, "unknown unit at {}-{}", a, b),
            DurationError::NumberTooLarge => write!(f, "number is too large"),
        }
    }
}

fn unit_multiplier(unit: &str) -> Option<(u64, u64)> {
    Some(match unit {
        "ns" | "nanos" => (0, 1),
        "us" => (0, 1_000),
        "ms" | "millis" => (0, 1_000_000),
        "s" | "sec" | "secs" | "second" | "seconds" => (1, 0),
        "m" | "min" | "mins" | "minute" | "minutes" => (60, 0),
        "h" | "hr" | "hrs" | "hour" | "hours" => (3_600, 0),
        "d" | "day" | "days" => (86_400, 0),
        "w" | "week" | "weeks" => (604_800, 0),
        "M" | "month" | "months" => (2_630_016, 0),
        "y" | "year" | "years" => (31_557_600, 0),
        _ => return None,
    })
}

fn parse_duration(src: &str) -> Result<Duration, String> {
    if src.trim().is_empty() {
        return Err(DurationError::Empty.to_string());
    }
    let chars: Vec<(usize, char)> = src.char_indices().collect();
    let end = src.len();
    let mut idx = 0usize;
    let mut duration = Duration::ZERO;
    let mut first_component = true;
    let mut next_expected_number_pos = 0usize;

    let cur = |idx: usize, chars: &Vec<(usize, char)>| -> Option<(usize, char)> {
        chars.get(idx).copied()
    };

    loop {
        while let Some((_, c)) = cur(idx, &chars) {
            if c.is_whitespace() {
                idx += 1;
            } else {
                break;
            }
        }
        let Some((_, first_ch)) = cur(idx, &chars) else {
            break;
        };
        if !first_ch.is_ascii_digit() {
            let pos = if first_component { 0 } else { next_expected_number_pos };
            return Err(DurationError::ExpectedNumber(pos).to_string());
        }

        // Parse a number, allowing whitespace between digits.
        let mut n: u64 = 0;
        loop {
            let Some((_, c)) = cur(idx, &chars) else { break };
            if c.is_ascii_digit() {
                let digit = c as u64 - '0' as u64;
                n = match n.checked_mul(10).and_then(|v| v.checked_add(digit)) {
                    Some(v) => v,
                    None => return Err(DurationError::NumberTooLarge.to_string()),
                };
                idx += 1;
            } else if c.is_whitespace() {
                let mut j = idx;
                while let Some((_, wc)) = cur(j, &chars) {
                    if wc.is_whitespace() { j += 1; } else { break; }
                }
                idx = j;
                // Continue if another digit follows; otherwise the
                // whitespace was a separator before the unit.
                match cur(idx, &chars) {
                    Some((_, nc)) if nc.is_ascii_digit() => continue,
                    _ => break,
                }
            } else {
                break;
            }
        }

        let unit_start = cur(idx, &chars).map(|x| x.0).unwrap_or(end);
        while let Some((_, c)) = cur(idx, &chars) {
            if c.is_ascii_alphabetic() {
                idx += 1;
            } else {
                break;
            }
        }
        let unit_end = cur(idx, &chars).map(|x| x.0).unwrap_or(end);
        if let Some((tpos, tch)) = cur(idx, &chars) {
            if !tch.is_whitespace() && !tch.is_ascii_digit() {
                return Err(DurationError::InvalidCharacter(tpos).to_string());
            }
        }
        let unit = &src[unit_start..unit_end];
        let Some((secs_mult, nanos_mult)) = unit_multiplier(unit) else {
            return Err(DurationError::UnknownUnit(unit_start, unit_end).to_string());
        };
        if secs_mult > 0 {
            let Some(add_secs) = n.checked_mul(secs_mult) else {
                return Err(DurationError::NumberTooLarge.to_string());
            };
            let Some(new_duration) = duration.checked_add(Duration::new(add_secs, 0)) else {
                return Err(DurationError::NumberTooLarge.to_string());
            };
            duration = new_duration;
        } else {
            let Some(total_nanos) = n.checked_mul(nanos_mult) else {
                return Err(DurationError::NumberTooLarge.to_string());
            };
            let add = Duration::new(total_nanos / 1_000_000_000, (total_nanos % 1_000_000_000) as u32);
            let Some(new_duration) = duration.checked_add(add) else {
                return Err(DurationError::NumberTooLarge.to_string());
            };
            duration = new_duration;
        }
        first_component = false;
        next_expected_number_pos = match cur(idx, &chars) {
            Some((p, c)) => p + c.len_utf8(),
            None => end,
        };
    }
    Ok(duration)
}

// ----- humantime-like RFC3339 parsing -----

const TS_INVALID: &str = "timestamp format is invalid";
const TS_DIGIT: &str = "bad character where digit is expected";
const TS_RANGE: &str = "numeric component is out of range";

fn is_leap(year: u64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}
fn days_in_month(year: u64, month: u64) -> u64 {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if is_leap(year) { 29 } else { 28 },
        _ => 0,
    }
}

fn parse_timestamp(src: &str) -> Result<SystemTime, &'static str> {
    let b = src.as_bytes();
    if b.len() < 19
        || b[4] != b'-'
        || b[7] != b'-'
        || (b[10] != b'T' && b[10] != b' ')
        || b[13] != b':'
        || b[16] != b':'
    {
        return Err(TS_INVALID);
    }
    let num = |start: usize, len: usize| -> Result<u64, &'static str> {
        let mut v: u64 = 0;
        for i in start..start + len {
            let c = b[i];
            if !c.is_ascii_digit() {
                return Err(TS_DIGIT);
            }
            v = v * 10 + (c - b'0') as u64;
        }
        Ok(v)
    };
    let year = num(0, 4)?;
    let month = num(5, 2)?;
    let day = num(8, 2)?;
    let hour = num(11, 2)?;
    let minute = num(14, 2)?;
    let second = num(17, 2)?;

    // Fractional seconds / Z suffix.
    let rest = &b[19..];
    let mut nanos: u32 = 0;
    if rest.is_empty() || rest == b"Z" {
        // no fraction
    } else if rest[0] == b'.' {
        let mut frac: &[u8] = &rest[1..];
        if frac.last() == Some(&b'Z') {
            frac = &frac[..frac.len() - 1];
        }
        for (i, &c) in frac.iter().enumerate() {
            if !c.is_ascii_digit() {
                return Err(TS_DIGIT);
            }
            if i < 9 {
                let mut pow: u32 = 1;
                for _ in 0..(8 - i) { pow *= 10; }
                nanos += (c - b'0') as u32 * pow;
            }
        }
    } else {
        return Err(TS_INVALID);
    }

    if !(1..=12).contains(&month)
        || day == 0
        || day > days_in_month(year, month)
        || hour > 23
        || minute > 59
        || second > 60
        || year < 1970
    {
        return Err(TS_RANGE);
    }

    let mut days: u64 = 0;
    for y in 1970..year {
        days += if is_leap(y) { 366 } else { 365 };
    }
    for m in 1..month {
        days += days_in_month(year, m);
    }
    days += day - 1;
    let secs = (((days * 24 + hour) * 60 + minute) * 60) + second;
    Ok(SystemTime::UNIX_EPOCH + Duration::new(secs, nanos))
}

// ----- tempfile -----

fn random_suffix() -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut buf = [0u8; 6];
    if let Ok(mut f) = File::open("/dev/urandom") {
        let _ = f.read_exact(&mut buf);
    } else {
        let seed = (process::id() as u64)
            ^ (SystemTime::now()
                .duration_since(SystemTime::UNIX_EPOCH)
                .map(|d| d.as_nanos() as u64)
                .unwrap_or(0));
        let mut x = seed ^ 0x9E3779B97F4A7C15;
        for item in &mut buf {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            *item = (x & 0xff) as u8;
        }
    }
    buf.iter().map(|b| CHARS[(*b % 62) as usize] as char).collect()
}

fn make_tempfile() -> io::Result<File> {
    let dir = env::temp_dir();
    for _ in 0..1000 {
        let path = dir.join(format!(".tmp{}", random_suffix()));
        match OpenOptions::new()
            .read(true)
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(&path)
        {
            Ok(file) => {
                fs::remove_file(&path)?;
                return Ok(file);
            }
            Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(e) => return Err(e),
        }
    }
    Err(io::Error::new(io::ErrorKind::AlreadyExists, "too many temporary file collisions"))
}

fn decimal_places(s: &str) -> usize {
    match s.find('.') {
        Some(p) => s[p + 1..].chars().take_while(|c| c.is_ascii_digit()).count(),
        None => 0,
    }
}

