    let command = parsed.input.join(" ");

    // Items, from --for first and then any standard-input lines.
    let mut items: Vec<String> = Vec::new();
    if let Some(ffor) = parsed.explicit_value("ffor") {
        for item in ffor.split(',') {
            items.push(item.to_string());
        }
    }
    let read_stdin = parsed.is_present("stdin") || !io::stdin().is_terminal();
    if read_stdin {
        let stdin = io::stdin();
        for line in stdin.lock().lines() {
            items.push(line.unwrap());
        }
    }

    if command.is_empty() {
        println!("No command supplied, exiting.");
        return;
    }

    let every_str = parsed.effective_value("every").unwrap();
    let every = parse_duration(every_str).unwrap();
    let for_duration: Option<Duration> = parsed
        .explicit_value("for_duration")
        .map(|v| parse_duration(v).unwrap());
    let until_time: Option<SystemTime> = parsed
        .explicit_value("until_time")
        .map(|v| parse_timestamp(v).unwrap());

    let count_by_str = parsed.effective_value("count_by").unwrap().to_string();
    let count_by: f64 = count_by_str.parse().unwrap();
    let count_places = decimal_places(&count_by_str);
    let offset: f64 = parsed.effective_value("offset").unwrap().parse().unwrap();

    let num_limit: Option<u64> = if let Some(v) = parsed.explicit_value("num") {
        let f: f64 = v.parse().unwrap();
        Some(f as u64)
    } else if !items.is_empty() {
        Some(items.len() as u64)
    } else {
        None
    };

    let until_contains: Option<String> = parsed.explicit_value("until_contains").map(|s| s.to_string());
    let until_match: Option<Regex> = parsed
        .explicit_value("until_match")
        .map(|s| Regex::new(s).unwrap());

    let mut effective_until_fail = parsed.is_present("until_fail");
    let mut until_error_specific: Option<u32> = None;
    if let Some(v) = parsed.explicit_value("until_error") {
        match v.parse::<u32>() {
            Ok(code) => until_error_specific = Some(code),
            Err(_) => effective_until_fail = true,
        }
    }

    let only_last = parsed.is_present("only_last");
    let summary = parsed.is_present("summary");
    let error_duration = parsed.is_present("error_duration");
    let until_success = parsed.is_present("until_success");
    let until_changes = parsed.is_present("until_changes");
    let until_same = parsed.is_present("until_same");

    let mut tmp = make_tempfile().unwrap();

    let mut actual: u64 = 0;
    let mut count: f64 = offset - count_by;
    let mut successes: u64 = 0;
    let mut failures: Vec<i32> = Vec::new();
    let mut first_output: Option<String> = None;
    let mut last_output = String::new();
    let mut duration_expired = false;

    loop {
        if let Some(limit) = num_limit {
            if actual >= limit {
                break;
            }
        }
        if let Some(d) = for_duration {
            if global_start.elapsed() >= d {
                duration_expired = true;
                break;
            }
        }
        if let Some(t) = until_time {
            if SystemTime::now() >= t {
                break;
            }
        }

        let iteration_start = Instant::now();
        count += count_by;

        env::set_var("COUNT", format!("{:.*}", count_places, count));
        env::set_var("ACTUALCOUNT", actual.to_string());
        let item_value: Option<&str> = if items.is_empty() {
            None
        } else if (actual as usize) < items.len() {
            Some(items[actual as usize].as_str())
        } else {
            Some(items[items.len() - 1].as_str())
        };
        if let Some(item) = item_value {
            env::set_var("ITEM", item);
        }

        tmp.set_len(0).unwrap();
        tmp.seek(SeekFrom::Start(0)).unwrap();
        let out_file = tmp.try_clone().unwrap();
        let err_file = tmp.try_clone().unwrap();

        let child_result = Command::new("sh")
            .arg("-c")
            .arg(&command)
            .stdout(Stdio::from(out_file))
            .stderr(Stdio::from(err_file))
            .spawn()
            .map_err(IoError);
        let mut child = child_result.unwrap();
        let status = child.wait().unwrap();

        if status.success() {
            successes += 1;
        } else {
            failures.push(status.code().unwrap_or(99));
        }

        tmp.seek(SeekFrom::Start(0)).unwrap();
        let mut output = String::new();
        tmp.read_to_string(&mut output).expect("read failed");

        let mut stop = false;
        if until_success && status.success() {
            stop = true;
        }
        if effective_until_fail && !status.success() {
            stop = true;
        }
        if let Some(target) = until_error_specific {
            if let Some(code) = status.code() {
                if code >= 0 && code as u32 == target {
                    stop = true;
                }
            }
        }

        for line in output.lines() {
            if let Some(pat) = &until_contains {
                if line.contains(pat.as_str()) {
                    stop = true;
                }
            }
            if let Some(re) = &until_match {
                if re.is_match(line) {
                    stop = true;
                }
            }
            if !only_last {
                println!("{}", line);
            }
        }

        if actual == 0 {
            first_output = Some(output.clone());
        } else if let Some(first) = &first_output {
            if until_changes && output != *first {
                stop = true;
            }
            if until_same && output == *first {
                stop = true;
            }
        }

        last_output = output;
        actual += 1;

        if stop {
            break;
        }

        let elapsed = iteration_start.elapsed();
        if elapsed < every {
            thread::sleep(every - elapsed);
        }
    }

    if only_last {
        for line in last_output.lines() {
            println!("{}", line);
        }
    }

    if summary {
        println!("Total runs:\t{}", actual);
        println!("Successes:\t{}", successes);
        if failures.is_empty() {
            println!("Failures:\t0");
        } else {
            let codes: Vec<String> = failures.iter().map(|c| c.to_string()).collect();
            println!("Failures:\t{} ({})", failures.len(), codes.join(", "));
        }
    }

    if error_duration && duration_expired {
        process::exit(124);
    }
}
