        }

        if c == '(' {
            if i + 1 < chars.len() && chars[i + 1] == '?' {
                let mut j = i + 2;
                while j < chars.len() && "imsxuU-R".contains(chars[j]) {
                    j += 1;
                }
                if j < chars.len() && chars[j] == ')' {
                    // Flag directive: not an expression factor.
                    i = j + 1;
