                }
                if j < chars.len() && chars[j] == ':' {
                    stack.push(Level::new());
                    i = j + 1;
                    continue;
                }
                if j < chars.len() && chars[j] == 'P' && j + 1 < chars.len() && chars[j + 1] == '<' {
                    let mut k = j + 2;
                    while k < chars.len() && chars[k] != '>' { k += 1; }
                    stack.push(Level::new());
                    i = k + 1;
                    continue;
