                            } else {
                                false
                            };
                            l.last_factor_empty = Some(now_empty);
                            l.just_repetition = true;
                            i = j + 1;
                            continue;
                        }
                    }
                }
            }
            if let Some(l) = stack.last_mut() { l.add_factor(false); }
            i += 1;
            continue;
        }

        if let Some(l) = stack.last_mut() { l.add_factor(false); }
        i += 1;
    }

    if let Some(top) = stack.last() {
        if top.has_alternation && top.branch_empty() {
            return true;
        }
    }
    false
}

