def jaro(s,t):
 if s==t:return 1.0
 ls=len(s);lt=len(t)
 if not ls or not lt:return 0.0
 md=max(ls,lt)//2-1
 sm=[0]*ls;tm=[0]*lt
 matches=0
 for i,ch in enumerate(s):
  lo=max(0,i-md);hi=min(i+md+1,lt)
  for j in range(lo,hi):
   if not tm[j] and ch==t[j]:sm[i]=1;tm[j]=1;matches+=1;break
 if not matches:return 0
 k=0;trans=0
 for i,ch in enumerate(s):
  if sm[i]:
   while not tm[k]:k+=1
   if ch!=t[k]:trans+=1
   k+=1
 return (matches/ls+matches/lt+(matches-trans//2)/matches)/3
def jw(s,t):
 j=jaro(s,t); 
 if j>.7:
  p=0
  for a,b in zip(s,t):
   if a==b and p<4:p+=1
   else:break
  j+=p*.1*(1-j)
 return j
for v in ['until','until-tame','until-']:
 for c in ['until-same','until-fail','until-time','until-success','until-changes']:
  print(v,c,jw(v,c),jw(c,v))
 print()
PY"}

