fn check_old_named_and_flag_syntax(value: &str) -> Option<String> {
    let chars: Vec<(usize, char)> = value.char_indices().collect();
    let mut i = 0usize;
    let mut in_class = false;
    let mut in_comment = false;
    let mut x_mode = false;
    let mut x_stack: Vec<bool> = Vec::new();

    while i < chars.len() {
        let c = chars[i].1;

        if in_comment {
            if c == '\n' {
                in_comment = false;
            }
