    let mut out = format!("regex parse error:\n{}\n", border);
    for (idx, line) in lines.iter().enumerate() {
        out.push_str(&format!("{:>width$}: {}\n", idx + 1, line, width = width));
        if !crosses_lines && idx + 1 == start_line {
            out.push_str(&" ".repeat(width + 2 + start_col));
            out.push_str(&"^".repeat(span_carets));
            out.push('\n');
        }
    }
    out.push_str(&border);
    out.push('\n');
    if crosses_lines {
        out.push_str(&format!(
            "on line {} (column {}) through line {} (column {})\n",
            start_line,
            start_col + 1,
            end_line,
            end_col
        ));
    }
    out.push_str(&format!("error: {}", message));
    out
}

fn char_at(chars: &[(usize, char)], idx: usize) -> Option<char> {
    chars.get(idx).map(|x| x.1)
}

// Detect older-regex-only rejections: (?<name>...) groups, the R flag,
// \b{start}-style assertions, and identity escapes of characters that
// are not in the old parser's meta-character set. Escapes and character
// classes are tracked, as is verbose (?x) mode.
fn check_old_named_and_flag_syntax(value: &str) -> Option<String> {
    let chars: Vec<(usize, char)> = value.char_indices().collect();
    let mut i = 0usize;
    let mut in_class = false;
    let mut in_comment = false;
    let mut x_mode = false;
    let mut x_stack: Vec<bool> = Vec::new();

    while i < chars.len() {
        let c = chars[i].1;

        if in_comment {
            if c == '\n' {
                in_comment = false;
            }
            i += 1;
            continue;
        }

        if c == '\\' {
            let byte_pos = chars[i].0;
            for special in ["start", "end", "start-half", "end-half"] {
                let wanted = format!("\\b{{{}}}", special);
                if value[byte_pos..].starts_with(&wanted) {
                    let (at, at_ch) = chars[i + 3];
                    return Some(format_regex_error(
                        value,
                        at,
                        at + at_ch.len_utf8(),
                        "repetition quantifier expects a valid decimal",
                    ));
                }
            }
            if let Some(&(next_pos, next_ch)) = chars.get(i + 1) {
                let old_meta = "#$&()*+-.?[\\]^{|}~";
                if next_ch.is_ascii()
                    && !next_ch.is_ascii_alphanumeric()
                    && !old_meta.contains(next_ch)
                    && !(x_mode && next_ch == ' ')
                {
                    return Some(format_regex_error(
                        value,
                        byte_pos,
                        next_pos + next_ch.len_utf8(),
                        "unrecognized escape sequence",
                    ));
                }
            }
            i += 2;
            continue;
        }

        if in_class {
            if c == ']' {
                in_class = false;
            }
            i += 1;
            continue;
        }

        if x_mode && c == '#' {
            in_comment = true;
            i += 1;
            continue;
        }

        if c == '[' {
            in_class = true;
            i += 1;
            continue;
        }

        if c == ')' {
            if let Some(previous) = x_stack.pop() {
                x_mode = previous;
            }
            i += 1;
            continue;
        }

        if c == '(' {
            if char_at(&chars, i + 1) != Some('?') {
                x_stack.push(x_mode);
                i += 1;
                continue;
            }

            // Parse a group prefix: optional flags, then either a
            // directive ')', a scoped group ':', or a capture name.
            let mut j = i + 2;
            let mut negative = false;
            let mut group_x_mode = x_mode;
            while let Some(fc) = char_at(&chars, j) {
                if fc == '-' {
                    negative = true;
                    j += 1;
                    continue;
                }
                if fc == 'R' {
                    let (at, at_ch) = chars[j];
                    return Some(format_regex_error(
                        value,
                        at,
                        at + at_ch.len_utf8(),
                        "unrecognized flag",
                    ));
                }
                if !"imsxuU".contains(fc) {
                    break;
                }
                if fc == 'x' {
                    group_x_mode = !negative;
                }
                j += 1;
            }

            match char_at(&chars, j) {
                Some('<')
                    if char_at(&chars, j + 1) != Some('=')
                        && char_at(&chars, j + 1) != Some('!') =>
                {
                    let (at, at_ch) = chars[j];
                    return Some(format_regex_error(
                        value,
                        at,
                        at + at_ch.len_utf8(),
                        "unrecognized flag",
                    ));
                }
                Some(')') => {
                    x_mode = group_x_mode;
                    i = j + 1;
                    continue;
                }
                Some(':') => {
                    x_stack.push(x_mode);
                    x_mode = group_x_mode;
                    i = j + 1;
                    continue;
                }
                Some('P') if char_at(&chars, j + 1) == Some('<') => {
                    x_stack.push(x_mode);
                    x_mode = group_x_mode;
                    let mut k = j + 2;
                    while k < chars.len() && chars[k].1 != '>' {
                        k += 1;
                    }
                    i = k + 1;
                    continue;
                }
                _ => {
                    x_stack.push(x_mode);
                    i += 1;
                    continue;
                }
            }
        }

        i += 1;
    }
    None
}

